	(-17, 'Nhà chính bang hội', '[]', '["Duyệt thành viên","Nâng cấp","Phong tước","Thay đổi khẩu hiệu","Rời bang"]', '[51,55,56,57,58]', 338, 125, 'dialog/empty.png', 0, '[-25,-25,50,50]'),
