INSERT INTO `task` (`taskId`, `type`, `name`, `description`, `guide`, `task`, `gift`, `fromNPC`, `taskNeed`) VALUES
	(1, 0, 'Nhiệm vụ 1', 'đánh 10 khủng long,10 tề thiên,10 gà rừng tại đấu trường\nPHẦN THƯỞNG:5 bùa cường hoá, 2 hồng ngọc, 10k ngọc', NULL, '[[0,10,6],[0,10,7],[0,10,3]]', '[[1,10000],[2,181,5],[2,182,2]]', -20, '[]'),
	(2, 0, 'Nhiệm vụ 2', 'đạt lv3: học 1 kĩ năng bất kì bạn nhé\nPHẦN THƯỞNG:1 nấm linh chi,5k ngọc', NULL, '[[1,3],[2,1]]', '[[1,5000],[2,179,1]]', -20, '[1]'),
	(3, 0, 'Nhiệm vụ 3', 'cộng 5 điểm gym rồi  quay lại tìm ta nhận thưởng nhé\nPHẦN THƯỞNG: 5k ngọc 1 bình x2 exp (khoá)', NULL, '[[14,5]]', '[[2,198,1,0],[1,5000]]', -20, '[2]'),
	(4, 0, 'Nhiệm vụ 4', 'Tốt lắm tới linh lâm tiêu diệt 30 mimon \nPHẦN THƯỞNG:2 nấm linh chi.10k ngọc', NULL, '[[0,30,14]]', '[[1,10000],[2,179,2]]', -20, '[3]'),
	(5, 0, 'Nhiệm vụ 5', 'Đạt lv5: Nâng cấp 1 kĩ năng lên lv3 nào \nPHẦN THƯỞNG:20k ngọc', NULL, '[[1,5],[3,1,3]]', '[[1,20000]]', -20, '[4]'),
	(6, 0, 'Nhiệm vụ 6', 'Tiếp Tục ghé lại linh lâm tiêu diệt 30 con pikachu,30 con tiểu miêu,40 con rùa baby nhé\nPHẦN THƯỞNG:1 lục bảo ngọc,20k ngọc,3 hồng ngọc', NULL, '[[0,30,15],[0,30,10],[0,40,1]]', '[[1,20000],[2,183,1],[2,182,3]]', -20, '[5]'),
	(7, 0, 'Nhiệm vụ 7', 'Đạt lv6: cường hoá trang bị bất kì lên up5\nPHẦN THƯỞNG:2 lục bảo ngọc,30k ngọc ', NULL, '[[1,6],[7,1,5]]', '[[1,30000],[2,183,2]]', -20, '[6]'),
	(8, 0, 'Nhiệm vụ 8', 'Đạt lv7: đánh 30 con bạch hổ tại đại linh cảnh\nPHẦN THƯỞNG:1 mảnh bạch hổ,15k ngọc', NULL, '[[1,7],[0,30,12]]', '[[1,15000],[2,743,1]]', -20, '[7]'),
