	(10, 0, 'Nhiệm vụ 10', 'Đạt lv10: tiến hoá trang bị bất kì \nPHẦN THƯỞNG:5 lục bảo ngọc,30k ngọc', NULL, '[[1,10],[6,1,1]]', '[[1,30000],[2,183,5]]', -20, '[9]'),
